const { chromium } = await import('playwright');
const browser = await chromium.launch({headless:true});
const page = await browser.newPage();
try {
  const resp = await page.goto('https://raw.githubusercontent.com/agent-ecosystem/agent-docs-spec/main/SPEC.md', {waitUntil:'domcontentloaded', timeout:30000});
  console.log('status', resp && resp.status());
  const text = await page.textContent('body');
  console.log('length', text.length);
  console.log('tail50', text.slice(-50));
  console.log('head200', text.slice(0,200));
} catch (e) {
  console.log('ERR', e && e.message);
}
await browser.close();
